PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS staff (id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, department_id INTEGER, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, staff_id INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(staff_id) REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY, type TEXT NOT NULL, department_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, expected_date TEXT, status TEXT NOT NULL DEFAULT 'Submitted', requester_id INTEGER NOT NULL, assignee_id INTEGER, assigned_role TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(requester_id) REFERENCES staff(id), FOREIGN KEY(assignee_id) REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS request_comments (id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL, author_id INTEGER NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(author_id) REFERENCES staff(id));
CREATE TABLE IF NOT EXISTS request_activity (id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL, actor_id INTEGER, action TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES requests(id), FOREIGN KEY(actor_id) REFERENCES staff(id));
